async downloadAttachmentFile(file, fullUrl) {
  const filename = file.name || this.getAttachmentName(file.url || '', 0)
  try {
    const res = await fetch(fullUrl, { credentials: 'same-origin' })
    if (!res.ok) throw new Error('fetch failed')
    const blob = await res.blob()
    downloadBlobFile(blob, filename)
  } catch (e) {
    try {
      const a = document.createElement('a')
      a.href = fullUrl
      a.download = filename
      a.rel = 'noopener noreferrer'
      a.style.display = 'none'
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
    } catch (e2) {
      if (this.$message) {
        this.$message.error('下载失败，请稍后重试')
      }
    }
  }
}

tool_input.new_string:
async downloadAttachmentFile(file, fullUrl) {
  const filename = file.name || this.getAttachmentName(file.url || '', 0)
  try {
    // 走统一鉴权下载通道（与 Vue.prototype.download / downloadGet 一致）：
    // 本应用文件接口需携带 token，裸 fetch 不带 token 会命中 401，
    // 失败后旧逻辑用 <a> 回退会把当前地址栏跳转到 /login（见禅道 6369）。
    await downloadGet(fullUrl, {}, filename)
  } catch (e) {
    // 兜底：新标签打开，避免当前页面被 302 重定向到登录页
    window.open(fullUrl, '_blank', 'noopener,noreferrer')
  }
}
